const fs = require('fs');
const path = require('path');
const axios = require('axios');

const DATA_DIR = '/data/csv';
const MOOSE_API = 'http://localhost:4000/ingest/Event';

// Helper function to parse different date formats
function parseDate(dateStr) {
  // Handle ISO format: 2026-01-15T10:00:00Z
  if (dateStr.includes('T') && dateStr.includes('Z')) {
    return new Date(dateStr).toISOString();
  }

  // Handle DD/MM/YYYY format: 15/01/2026
  if (dateStr.includes('/')) {
    const [day, month, year] = dateStr.split('/');
    return new Date(`${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}T00:00:00Z`).toISOString();
  }

  return new Date(dateStr).toISOString();
}

// Helper function to parse value field
function parseValue(valueStr) {
  if (!valueStr || valueStr.trim() === '' || valueStr === 'N/A' || valueStr === 'null') {
    return 0;
  }
  return parseFloat(valueStr);
}

// Function to clean and parse CSV content
function parseCSV(content) {
  const lines = content.trim().split('\n');
  const events = [];
  let headerSeen = false;

  for (let line of lines) {
    // Remove trailing commas
    line = line.replace(/,+$/, '');

    // Skip empty lines
    if (!line.trim()) continue;

    // Skip header lines (first occurrence and any duplicates)
    if (line.startsWith('event_id,')) {
      headerSeen = true;
      continue;
    }

    if (!headerSeen) continue;

    const parts = line.split(',');
    if (parts.length >= 5) {
      try {
        const event = {
          event_id: parts[0].trim(),
          event_ts: parseDate(parts[1].trim()),
          user_id: parts[2].trim(),
          event_type: parts[3].trim(),
          value: parseValue(parts[4].trim())
        };
        events.push(event);
      } catch (error) {
        console.error(`Error parsing line: ${line}`, error);
      }
    }
  }

  return events;
}

// Function to load data from all CSV files
async function loadAllData() {
  const files = fs.readdirSync(DATA_DIR).filter(file => file.endsWith('.csv'));
  let allEvents = [];

  console.log(`Found ${files.length} CSV files`);

  for (const file of files) {
    console.log(`Processing ${file}...`);
    const filePath = path.join(DATA_DIR, file);
    const content = fs.readFileSync(filePath, 'utf8');
    const events = parseCSV(content);
    allEvents.push(...events);
    console.log(`  - Parsed ${events.length} events from ${file}`);
  }

  console.log(`\nTotal events to load: ${allEvents.length}`);

  // Send events to Moose
  for (let i = 0; i < allEvents.length; i++) {
    const event = allEvents[i];
    try {
      const response = await axios.post(MOOSE_API, event, {
        headers: {
          'Content-Type': 'application/json'
        }
      });
      console.log(`✓ Loaded event ${i + 1}/${allEvents.length}: ${event.event_id}`);
    } catch (error) {
      console.error(`✗ Failed to load event ${event.event_id}:`, error.response?.data || error.message);
    }
  }

  console.log('\nData loading completed!');
  return allEvents;
}

// Run the data loading
loadAllData().catch(console.error);

